<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Grupo BCMR</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#172033;background:#f6f7fb}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1180px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center}.brand b{font-size:22px}.hero{margin:28px 0;padding:34px;border-radius:24px;background:#15233e;color:white}.hero h1{max-width:700px;font-size:42px;margin:8px 0}.tabs,.grid{display:grid;gap:14px}.tabs{grid-template-columns:repeat(3,1fr)}.card{background:white;border:1px solid #e3e7ef;border-radius:18px;padding:18px}.tab{cursor:pointer}.panel{display:none;margin-top:20px}.panel.active{display:block}.grid.products{grid-template-columns:repeat(3,1fr)}button,input,textarea,select{font:inherit}button{border:0;border-radius:12px;padding:11px 15px;cursor:pointer;background:#1d4ed8;color:white}input,textarea,select{width:100%;border:1px solid #d9deea;border-radius:10px;padding:11px;margin-top:5px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.muted{color:#64748b}.cart{position:sticky;bottom:12px}.msg{margin-top:12px;font-weight:600}@media(max-width:760px){.tabs,.grid.products,.fields{grid-template-columns:1fr}.hero h1{font-size:31px}.wrap{padding:16px}}
</style></head><body><main class="wrap"><div class="top"><div class="brand"><b>Grupo BCMR</b><div class="muted">Comercial · Manutenções · Transportes</div></div><a href="../login.php">Área ADM</a></div><section class="hero"><small>UM ÚNICO ECOSSISTEMA</small><h1>Comprar, solicitar manutenção ou agendar uma viagem.</h1><p>As três empresas do Grupo BCMR integradas em um só lugar.</p></section><div class="tabs"><div class="card tab" data-tab="loja"><b>🛒 Comercial Marques</b><p class="muted">Eletrônicos e maquininhas</p></div><div class="card tab" data-tab="servico"><b>🔧 Manutenções Marques</b><p class="muted">Solicite e acompanhe</p></div><div class="card tab" data-tab="viagem"><b>🚐 Transportes BCMR</b><p class="muted">Agende e acompanhe viagens</p></div></div>
<section id="loja" class="panel active"><h2>Produtos</h2><div id="products" class="grid products"></div><div class="card cart"><b>Carrinho</b><div id="cartItems" class="muted">Vazio</div><h3 id="cartTotal">R$ 0,00</h3><div class="fields"><label>Nome<input id="buyerName"></label><label>Telefone<input id="buyerPhone"></label><label>E-mail<input id="buyerEmail" type="email"></label><label>Pagamento<select id="pay"><option>PIX</option><option>CARTAO</option><option>LINK_PAGAMENTO</option></select></label></div><button id="checkout">Criar pedido</button><div id="shopMsg" class="msg"></div></div></section>
<section id="servico" class="panel"><div class="card"><h2>Solicitar manutenção</h2><div class="fields"><label>Cliente<input id="sCliente"></label><label>Equipamento<input id="sEquip"></label><label style="grid-column:1/-1">Problema<textarea id="sProb"></textarea></label></div><button id="createService">Gerar protocolo</button><div id="sMsg" class="msg"></div></div><div class="card"><h3>Acompanhar protocolo</h3><input id="sProtocol" placeholder="MM-..."><button id="trackService">Consultar</button><pre id="sTrack"></pre></div></section>
<section id="viagem" class="panel"><div class="card"><h2>Solicitar viagem</h2><div class="fields"><label>Cliente<input id="vCliente"></label><label>Passageiros<input id="vPass" type="number" value="1" min="1"></label><label>Origem<input id="vOrig"></label><label>Destino<input id="vDest"></label><label>Data e hora<input id="vData" type="datetime-local"></label><label>Tipo<input id="vTipo" placeholder="Executivo"></label></div><button id="createTrip">Solicitar</button><div id="vMsg" class="msg"></div></div><div class="card"><h3>Acompanhar viagem</h3><input id="vCode" placeholder="BCMR-..."><button id="trackTrip">Consultar</button><pre id="vTrack"></pre></div></section></main><script>
const $=s=>document.querySelector(s),fmt=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v),api=async(u,o={})=>{const r=await fetch('../'+u,{headers:{'Content-Type':'application/json'},...o});const j=await r.json();if(!j.status)throw Error(j.mensagem);return j.dados};document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.panel').forEach(p=>p.classList.remove('active'));$('#'+t.dataset.tab).classList.add('active')});let catalog=[],cart=[];async function load(){const d=await api('api/publico/catalogo.php');catalog=d.produtos;$('#products').innerHTML=catalog.map(p=>`<div class="card"><small>${p.categoria||''}</small><h3>${p.nome}</h3><b>${fmt(p.preco_venda)}</b><p>${p.estoque_atual} em estoque</p><button onclick="add(${p.id})">Adicionar</button></div>`).join('')}window.add=id=>{const p=catalog.find(x=>+x.id===id),x=cart.find(x=>x.produto_id===id);if(x)x.quantidade++;else cart.push({produto_id:id,quantidade:1,nome:p.nome,preco:+p.preco_venda});render()};function render(){const total=cart.reduce((s,x)=>s+x.preco*x.quantidade,0);$('#cartItems').textContent=cart.length?cart.map(x=>`${x.quantidade}x ${x.nome}`).join(' · '):'Vazio';$('#cartTotal').textContent=fmt(total)}$('#checkout').onclick=async()=>{try{const d=await api('api/pedidos/criar_publico.php',{method:'POST',body:JSON.stringify({cliente:{nome:$('#buyerName').value,telefone:$('#buyerPhone').value,email:$('#buyerEmail').value},itens:cart.map(({produto_id,quantidade})=>({produto_id,quantidade})),forma_pagamento:$('#pay').value,gateway:'A_CONFIGURAR'})});$('#shopMsg').textContent=`Pedido ${d.codigo} criado. Total ${fmt(d.total)}. Reserva por 30 minutos.`;cart=[];render();load()}catch(e){$('#shopMsg').textContent=e.message}};$('#createService').onclick=async()=>{try{const d=await api('api/publico/servico_criar.php',{method:'POST',body:JSON.stringify({cliente:$('#sCliente').value,equipamento:$('#sEquip').value,problema:$('#sProb').value})});$('#sMsg').textContent='Protocolo: '+d.protocolo;$('#sProtocol').value=d.protocolo}catch(e){$('#sMsg').textContent=e.message}};$('#trackService').onclick=async()=>{try{const d=await api('api/publico/servico_consultar.php?protocolo='+encodeURIComponent($('#sProtocol').value));$('#sTrack').textContent=JSON.stringify(d.servico,null,2)}catch(e){$('#sTrack').textContent=e.message}};$('#createTrip').onclick=async()=>{try{const d=await api('api/publico/viagem_criar.php',{method:'POST',body:JSON.stringify({cliente:$('#vCliente').value,origem:$('#vOrig').value,destino:$('#vDest').value,data_saida:$('#vData').value.replace('T',' ')+':00',passageiros:+$('#vPass').value,tipo:$('#vTipo').value})});$('#vMsg').textContent='Código: '+d.codigo;$('#vCode').value=d.codigo}catch(e){$('#vMsg').textContent=e.message}};$('#trackTrip').onclick=async()=>{try{const d=await api('api/publico/viagem_consultar.php?codigo='+encodeURIComponent($('#vCode').value));$('#vTrack').textContent=JSON.stringify(d.viagem,null,2)}catch(e){$('#vTrack').textContent=e.message}};load();
</script></body></html>
